if [ -d "/Applications/LibreWolf.app" ]; then
    rm -rf "/Applications/LibreWolf.app" 2>/dev/null || true
elif [ -f "/Applications/LibreWolf.app" ]; then
    rm -f "/Applications/LibreWolf.app" 2>/dev/null || true
fi

